// Generate `<map>.outline.json` sidecars for the county maps: a simplified
// silhouette of each map's road-network footprint, in the map's own local
// frame. The county-jump overlay draws this instead of a bounding box, so a
// neighbouring county reads as geography (coastline, bay, empty hills) rather
// than UI. Derived entirely from the committed map scrape — no coordinates
// live in the repo (`web/public/*.json` is gitignored) — and regenerated by
// the predev/prebuild hooks.
//
//   node scripts/build-outlines.mjs [--debug]   (--debug prints ASCII previews)

import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { gunzipSync } from "node:zlib";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const debug = process.argv.includes("--debug");

// The county-flagged entries of REAL_MAPS, read from the source of truth so a
// newly flagged county needs no change here.
const mapsTs = readFileSync(join(root, "src/lib/maps.ts"), "utf8");
const county = [...mapsTs.matchAll(/\w+:\s*\{\s*file:\s*"([^"]+)"[^}]*county:\s*true/g)].map((m) => m[1]);

// Grid resolution: fine enough that the bay/coast indentations survive, coarse
// enough that ordinary road spacing fills the interior solid.
const GRID = 72;

for (const file of county) {
  const gz = join(root, "public", `${file}.gz`);
  if (!existsSync(gz)) {
    console.warn(`outlines: missing ${file}.gz — skipped`);
    continue;
  }
  const doc = JSON.parse(gunzipSync(readFileSync(gz)).toString());
  const pts = doc.nodes.map((n) => [n.x, n.y]);
  const xs = pts.map((p) => p[0]);
  const ys = pts.map((p) => p[1]);
  const [x0, x1] = [Math.min(...xs), Math.max(...xs)];
  const [y0, y1] = [Math.min(...ys), Math.max(...ys)];
  const cell = Math.max((x1 - x0) / GRID, (y1 - y0) / GRID);
  const [w, h] = [Math.ceil((x1 - x0) / cell) + 1, Math.ceil((y1 - y0) / cell) + 1];

  // Presence grid (padded 1 cell so contours always close), one dilation pass
  // to bridge rural road spacing.
  const idx = (x, y) => (y + 1) * (w + 2) + (x + 1);
  let g = new Uint8Array((w + 2) * (h + 2));
  for (const [px, py] of pts) {
    g[idx(Math.floor((px - x0) / cell), Math.floor((py - y0) / cell))] = 1;
  }
  const dilated = new Uint8Array(g.length);
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      let any = 0;
      for (let dy = -1; dy <= 1 && !any; dy++) {
        for (let dx = -1; dx <= 1 && !any; dx++) {
          any = g[idx(x + dx, y + dy)];
        }
      }
      dilated[idx(x, y)] = any;
    }
  }
  g = dilated;

  if (debug) {
    let art = `\n${file} (${w}×${h}, cell ${(cell / 1000).toFixed(2)} km)\n`;
    for (let y = h - 1; y >= 0; y -= 2) {
      let line = "";
      for (let x = 0; x < w; x++) line += g[idx(x, y)] ? "█" : "·";
      art += line + "\n";
    }
    console.log(art);
  }

  // Marching squares over cell corners → boundary segments (edge midpoints),
  // chained into loops; keep the longest.
  const segs = [];
  const at = (x, y) => g[idx(x, y)];
  for (let y = -1; y < h; y++) {
    for (let x = -1; x < w; x++) {
      const c = (at(x, y) << 0) | (at(x + 1, y) << 1) | (at(x + 1, y + 1) << 2) | (at(x, y + 1) << 3);
      // Edge midpoints of the cell square spanning corners (x,y)..(x+1,y+1).
      const S = [x + 0.5, y];
      const E = [x + 1, y + 0.5];
      const N = [x + 0.5, y + 1];
      const W = [x, y + 0.5];
      const table = {
        1: [[W, S]], 2: [[S, E]], 3: [[W, E]], 4: [[E, N]], 5: [[W, N], [S, E]],
        6: [[S, N]], 7: [[W, N]], 8: [[N, W]], 9: [[N, S]], 10: [[N, E], [S, W]],
        11: [[N, E]], 12: [[E, W]], 13: [[E, S]], 14: [[S, W]],
      };
      for (const [a, b] of table[c] ?? []) segs.push([a, b]);
    }
  }
  const keyOf = (p) => `${p[0]},${p[1]}`;
  const from = new Map();
  for (const [a, b] of segs) from.set(keyOf(a), [a, b]);
  const seen = new Set();
  let best = [];
  for (const [k, [a]] of from) {
    if (seen.has(k)) continue;
    const loop = [];
    let cur = a;
    while (cur && !seen.has(keyOf(cur))) {
      seen.add(keyOf(cur));
      loop.push(cur);
      cur = from.get(keyOf(cur))?.[1];
    }
    if (loop.length > best.length) best = loop;
  }

  // Douglas–Peucker at ~¾ cell, then back to metres in the map's local frame.
  const simplify = (line, tol) => {
    if (line.length < 3) return line;
    const keep = new Uint8Array(line.length);
    keep[0] = keep[line.length - 1] = 1;
    const stack = [[0, line.length - 1]];
    while (stack.length) {
      const [i, j] = stack.pop();
      const [ax, ay] = line[i];
      const [bx, by] = line[j];
      const [dx, dy] = [bx - ax, by - ay];
      const len = Math.hypot(dx, dy) || 1;
      let far = -1;
      let fd = tol;
      for (let k = i + 1; k < j; k++) {
        const d = Math.abs((line[k][0] - ax) * dy - (line[k][1] - ay) * dx) / len;
        if (d > fd) {
          fd = d;
          far = k;
        }
      }
      if (far > 0) {
        keep[far] = 1;
        stack.push([i, far], [far, j]);
      }
    }
    return line.filter((_, i) => keep[i]);
  };
  const points = simplify(best, 0.75).map(([gx, gy]) => [
    Math.round(x0 + gx * cell),
    Math.round(y0 + gy * cell),
  ]);

  const out = { origin: doc.meta.origin, points };
  const path = join(root, "public", `${file.replace(/\.json$/, "")}.outline.json`);
  writeFileSync(path, JSON.stringify(out));
  console.log(`outlines: ${file} → ${points.length} points (${best.length} raw), ${JSON.stringify(out).length} bytes`);
}
